private fun formatDate(dateStr: String): String {
    if (dateStr.isBlank()) return ""
    return try {
        // Parse ISO date and format for display
        // Input: "2026-02-24T10:30:00.000000Z" or "2026-02-24 10:30:00"
        val datePart = dateStr.take(10) // "2026-02-24"
        val parts = datePart.split("-")
        if (parts.size == 3) {
            val month = when (parts[1]) {
                "01" -> "Jan"; "02" -> "Feb"; "03" -> "Mar"; "04" -> "Apr"
                "05" -> "May"; "06" -> "Jun"; "07" -> "Jul"; "08" -> "Aug"
                "09" -> "Sep"; "10" -> "Oct"; "11" -> "Nov"; "12" -> "Dec"
                else -> parts[1]
            }
            "${parts[2].trimStart('0')} $month ${parts[0]}"
        } else {
            datePart
        }
    } catch (e: Exception) {
        dateStr.take(10)
    }
}

@Composable
private fun formatDate(dateStr: String): String {
    if (dateStr.isBlank()) return ""
    val months = stringArrayResource(R.array.month_abbreviations)
    return try {
        // Parse ISO date and format for display
        // Input: "2026-02-24T10:30:00.000000Z" or "2026-02-24 10:30:00"
        val datePart = dateStr.take(10) // "2026-02-24"
        val parts = datePart.split("-")
        if (parts.size == 3) {
            val month = parts[1].toIntOrNull()
                ?.takeIf { it in 1..12 }
                ?.let { months[it - 1] }
                ?: parts[1]
            stringResource(R.string.history_date, parts[2].trimStart('0'), month, parts[0])
        } else {
            datePart
        }
    } catch (e: Exception) {
        dateStr.take(10)
    }
}
